<?php
declare(strict_types=1);
$runtime=file_get_contents(__DIR__.'/install-runtime.php');
$start= <<<'SH'
#!/bin/sh
# Generated by scripts/distribution/render-installer.php. Runtime: sh + PHP + curl.
# The whole function is parsed before invocation, including when piped to sh.
set -eu
asyncara_install_main() {
    asyncara_php=${ASYNCARA_PHP:-php}
    command -v "$asyncara_php" >/dev/null 2>&1 || { echo 'PHP CLI is required; set ASYNCARA_PHP to select it.' >&2; return 1; }
    umask 077
    asyncara_tmp=$(mktemp -d "${TMPDIR:-/tmp}/asyncara-install.XXXXXXXX")
    trap 'rm -rf "$asyncara_tmp"' EXIT
    trap 'exit 130' INT
    trap 'exit 143' TERM HUP
    cat > "$asyncara_tmp/install.php" <<'ASYNCARA_INSTALLER_PHP'
SH;
$end= <<<'SH'
ASYNCARA_INSTALLER_PHP
    "$asyncara_php" -n "$asyncara_tmp/install.php" "$@"
}
asyncara_install_main "$@"
SH;
$content=$start."\n".$runtime.$end."\n";
$target=dirname(__DIR__).'/install.sh';
$checksum=hash('sha256',$content)."  install.sh\n";
if(in_array('--check',$argv,true)) {
    if(file_get_contents($target)!==$content || !is_file($target.'.sha256') || file_get_contents($target.'.sha256')!==$checksum)
        throw new RuntimeException('Regenerate scripts/install.sh and its checksum');
}
else { file_put_contents($target,$content);chmod($target,0755);file_put_contents($target.'.sha256',$checksum); }
